CREATE TABLE IF NOT EXISTS public.invoices (id uuid DEFAULT gen_random_uuid() PRIMARY KEY, organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, invoice_number text NOT NULL, customer_name text NOT NULL, customer_email text, amount numeric(14,2) NOT NULL CHECK (amount >= 0), currency text NOT NULL DEFAULT 'KES', status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ISSUED','PAID','VOID','OVERDUE')), due_date date, issued_at timestamptz, paid_at timestamptz, notes text, created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id, invoice_number));